import { expect, test, type APIRequestContext, type Request } from '@playwright/test';
import { STRAPI_URL, adminCredentials } from './support/env';
import { CL_LABELS, CO_LABELS, field, visibleLabels } from './support/form';
import {
  createField,
  createScopedToken,
  deleteField,
  deleteStaleFields,
  deleteStaleTokens,
  deleteToken,
  findCountryDocumentId,
  loginAdmin,
  type AdminSession,
  type ScopedToken,
} from './support/strapi-admin';

/**
 * US-01-AC-03: a field published in Strapi appears on the next reload with no code change and no
 * deployment. The content is written from the Node test process following the ADR-0002 write flow;
 * the credentials never reach the browser context.
 */

const TOKEN_NAME = 'us-01-ac-03-e2e';
const FIELD_KEY = 'mobilePhone';

test.describe.configure({ mode: 'serial' });

test.describe('US-01-AC-03 configuration change without deployment', () => {
  let api: APIRequestContext;
  let session: AdminSession | undefined;
  let token: ScopedToken | undefined;
  let createdDocumentId: string | undefined;

  test.beforeAll(async ({ playwright }) => {
    api = await playwright.request.newContext({ baseURL: STRAPI_URL });
  });

  // Teardown deletes the field, then the token, even when the test failed. Each step is attempted.
  test.afterAll(async () => {
    const failures: string[] = [];
    if (token && createdDocumentId) {
      try {
        await deleteField(api, token, createdDocumentId);
      } catch (error) {
        failures.push(String(error));
      }
    }
    if (session && token) {
      try {
        await deleteToken(api, session, token.id);
      } catch (error) {
        failures.push(String(error));
      }
    }
    await api.dispose();
    expect(failures, 'teardown must delete the field and the scoped token').toEqual([]);
  });

  test('US-01-AC-03 a new published field for Colombia appears between "Nombre completo" and "Fecha de nacimiento" on reload, and not in Chile', async ({ page }) => {
    const browserRequests: Request[] = [];
    page.on('request', (request) => browserRequests.push(request));

    // Pre-test cleanup of leftovers of a crashed run, then the scoped token for this run.
    const { email, password } = adminCredentials();
    session = await loginAdmin(api, email, password);
    await deleteStaleTokens(api, session, TOKEN_NAME);
    token = await createScopedToken(api, session, TOKEN_NAME);
    await deleteStaleFields(api, token, FIELD_KEY);

    // Before: the seeded form.
    await page.goto('/co/datos');
    await expect(field(page, 'Placa')).toBeVisible();
    expect(await visibleLabels(page)).toEqual(CO_LABELS);

    // The business team adds and publishes the field (key mobilePhone, sortOrder 35, not required).
    const countryDocumentId = await findCountryDocumentId(api, 'CO');
    createdDocumentId = await createField(api, token, countryDocumentId, {
      key: FIELD_KEY,
      type: 'text',
      label: 'Teléfono celular',
      isRequired: false,
      sortOrder: 35,
      errorMessage: 'Ingresa un número de celular válido.',
    });

    // The running front end and its configuration are not touched. I reload.
    await page.reload();
    await expect(field(page, 'Teléfono celular')).toBeVisible();
    const labels = await visibleLabels(page);
    expect(labels).toEqual([
      'Tipo de documento',
      'Número de documento',
      'Nombre completo',
      'Teléfono celular',
      'Fecha de nacimiento',
      'Ciudad',
      'Placa',
      'Marca',
      'Línea',
      'Modelo (año)',
      'Autorizo el tratamiento de mis datos personales.',
    ]);

    // It is optional: no required marker semantics, and leaving it empty does not block the form.
    await expect(field(page, 'Teléfono celular')).not.toHaveAttribute('aria-required', 'true');

    // The field does not appear in the context of Chile.
    await page.goto('/cl/datos');
    await expect(field(page, 'Patente')).toBeVisible();
    expect(await visibleLabels(page)).toEqual(CL_LABELS);

  test('US-01-AC-28 through the proxy the upper-case path and the non-Bearer Authorization variants reveal no draft', async ({ request }) => {
    for (const prefix of PATH_PREFIXES) {
      await expectNoDraft(await request.get(`${prefix}/form-fields`, { params: DRAFT_QUERY }), `proxy ${prefix}`);
      await expectNoDraft(await request.get(`${prefix}/countries`, { params: { status: 'draft' } }), `proxy ${prefix} countries`);
    }
    for (const headers of NON_BEARER_HEADERS) {
      await expectNoDraft(await request.get('/api/form-fields', { params: DRAFT_QUERY, headers }), `proxy Authorization "${Object.values(headers)[0]}"`);
    }
  });

  test('US-01-AC-28 a request with a valid scoped token is still allowed what ADR-0005 permits (country find), and an invalid Bearer is refused', async ({ playwright }) => {
    // Guards against fixing F01 by refusing every Authorization header. Only the permitted read is
    // asserted: what the token may see with status=draft is deliberately not constrained here.
    const strapi = await playwright.request.newContext({ baseURL: STRAPI_URL });
    const { email, password } = adminCredentials();
    const tokenName = 'US-01-AC-28 e2e token';
    const session = await loginAdmin(strapi, email, password);
    await deleteStaleTokens(strapi, session, tokenName);
    const token = await createScopedToken(strapi, session, tokenName);
    try {
      const allowed = await strapi.get('/api/countries', { headers: { Authorization: `Bearer ${token.accessKey}` } });
      expect(allowed.status()).toBe(200);
      expect((await items(allowed)).length).toBeGreaterThan(0);

      const invalid = await strapi.get('/api/form-fields', {
        params: DRAFT_QUERY,
        headers: { Authorization: 'Bearer not-a-real-token-for-a-negative-test' }, // scan-secrets: allow (fictitious value, negative test for ADR-0002)
      });
      expect(invalid.status()).toBe(401);
    } finally {
      await deleteToken(strapi, session, token.id);
      await strapi.dispose();
    }
  });
});
